-- Schema baseline. Production deployment uses EF Core MigrateAsync.
CREATE TABLE IF NOT EXISTS AttendanceProfiles (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, EmployeeCode TEXT, Enabled INTEGER NOT NULL, Website1Enabled INTEGER NOT NULL, Website2Enabled INTEGER NOT NULL, Website1Username TEXT NOT NULL, Website1PasswordEncrypted TEXT, Website2Username TEXT NOT NULL, Website2PasswordEncrypted TEXT, QueueOrder INTEGER NOT NULL, Notes TEXT, CreatedAt TEXT NOT NULL, UpdatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Schedules (Id INTEGER PRIMARY KEY AUTOINCREMENT, AttendanceType INTEGER NOT NULL, Enabled INTEGER NOT NULL, LocalTime TEXT NOT NULL, ActiveDays INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS AttendanceRuns (Id INTEGER PRIMARY KEY AUTOINCREMENT, AttendanceType INTEGER NOT NULL, ScheduledAt TEXT NOT NULL, StartedAt TEXT, FinishedAt TEXT, Status INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS AttendanceResults (Id INTEGER PRIMARY KEY AUTOINCREMENT, AttendanceRunId INTEGER NOT NULL, ProfileId INTEGER NOT NULL, Provider INTEGER NOT NULL, AttendanceType INTEGER NOT NULL, Status INTEGER NOT NULL, Attempt INTEGER NOT NULL, StartedAt TEXT NOT NULL, FinishedAt TEXT, ResultMessage TEXT, ScreenshotPath TEXT, ErrorCode TEXT, ErrorMessage TEXT);
CREATE TABLE IF NOT EXISTS ApplicationSettings (Key TEXT PRIMARY KEY, Value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS TelegramSettings (Id INTEGER PRIMARY KEY AUTOINCREMENT, Enabled INTEGER NOT NULL, BotTokenEncrypted TEXT, ChatId TEXT, NotifySuccess INTEGER NOT NULL, NotifyFailure INTEGER NOT NULL, SendSummary INTEGER NOT NULL, SendScreenshot INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS AuditLogs (Id INTEGER PRIMARY KEY AUTOINCREMENT, Timestamp TEXT NOT NULL, Level TEXT NOT NULL, Category TEXT NOT NULL, Action TEXT NOT NULL, ProfileId INTEGER, Message TEXT NOT NULL);
